return async function(config, file, ctx) {
  const baseUrl = String(config.baseUrl || '').trim().replace(/\/+$/, '');
  if (!baseUrl) throw new Error('Missing OneFile URL');

  const authMode = String(config.authMode || 'api_key');
  const headers = { 'Accept': 'application/json, text/plain, */*' };
  let uploadUrl = '';

  if (authMode === 'public_upload') {
    const publicUpload = String(config.publicUpload || '').trim();
    if (!publicUpload) throw new Error('Missing public upload UUID or URL');
    if (/^https?:\/\//i.test(publicUpload)) {
      uploadUrl = publicUpload;
    } else {
      const uuid = publicUpload.replace(/^\/+|\/+$/g, '').replace(/^api\/public-uploads\//i, '');
      uploadUrl = baseUrl + '/api/public-uploads/' + encodeURIComponent(uuid);
    }
  } else {
    const apiKey = String(config.apiKey || '').trim();
    if (!apiKey) throw new Error('Missing API key');
    headers.Authorization = 'Bearer ' + apiKey;
    uploadUrl = baseUrl + '/api/uploads/direct';
  }

  const blob = await (await fetch(file.data)).blob();
  const fd = new FormData();
  fd.append('file', blob, file.name);
  fd.append('original_filename', file.name);

  const keyPrefix = String(config.keyPrefix || '').trim().replace(/^\/+|\/+$/g, '');
  if (keyPrefix) {
    const safeName = String(file.name || 'image').replace(/^\/+/, '');
    fd.append('object_key', keyPrefix + '/' + safeName);
  }

  const res = await ctx.fetch(uploadUrl, { method: 'POST', headers, body: fd });
  const json = res.body;
  if (!res.ok || (json && json.error)) {
    const message = json && json.error ? json.error.message : (json && (json.message || json.msg));
    throw new Error(message || ('HTTP ' + res.status));
  }

  const data = json && json.data ? json.data : json;
  const url = data && (data.url || data.location);
  if (!url) throw new Error('Upload succeeded but OneFile did not return a public URL. Check the bucket Public URL setting.');
  return url;
}
